import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"篇525｜万族自选命运机制·总论——命运选择权交还众生","description":"","frontmatter":{"title":"篇525｜万族自选命运机制·总论——命运选择权交还众生","no":525,"module":3,"tags":["万族自选命运","总论","选择权","命运","万族共和"],"related":["05-万族共进基本纲领","08-人人有路保障体系","40-共生宪法总纲"]},"headers":[],"relativePath":"zh/525_模块3-万族自选命运总论.md","filePath":"zh/525_模块3-万族自选命运总论.md"}'),l={name:"zh/525_模块3-万族自选命运总论.md"};function i(h,t,n,d,s,u){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="篇525-万族自选命运机制·总论——命运选择权交还众生" tabindex="-1">篇525｜万族自选命运机制·总论——命运选择权交还众生 <a class="header-anchor" href="#篇525-万族自选命运机制·总论——命运选择权交还众生" aria-label="Permalink to &quot;篇525｜万族自选命运机制·总论——命运选择权交还众生&quot;">​</a></h1><blockquote><p>所属模块：模块三·双轨时间域｜对标地基：文档05、08、40</p></blockquote><h2 id="引言-最高的尊重-是把选择权交出去" tabindex="-1">引言：最高的尊重，是把选择权交出去 <a class="header-anchor" href="#引言-最高的尊重-是把选择权交出去" aria-label="Permalink to &quot;引言：最高的尊重，是把选择权交出去&quot;">​</a></h2><p>掠夺派体系对众生命运的态度，从一开始就是决定好的：主角是天选之子，配角是工具，凡人是尘埃，外族是敌人或奴隶。整个宇宙的命运由一个人或一个家族决定。衡元宙对这种安排的根本否定，体现在一个制度上——<strong>万族自选命运机制</strong>：每个生灵、每个种族、每个文明，都有权选择自己走哪条修炼路径、用多快的速度、过什么样的生活。六大顶层公理是这一机制的最高原则：反掠夺主义公理禁止替他人决定命运；万族共和公理承认众生平等的选择权；集体升维公理要求自选命运的最终方向仍是共建；因果自律公理要求选择权不被滥用去伤害他人；法则优先公理要求选择规则稳定不变。众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><p>本篇作为万族自选命运机制的总纲，给出整体设计。</p><h2 id="一、自选命运的三层含义" tabindex="-1">一、自选命运的三层含义 <a class="header-anchor" href="#一、自选命运的三层含义" aria-label="Permalink to &quot;一、自选命运的三层含义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>内容</th><th>举例</th></tr></thead><tbody><tr><td>个体层</td><td>每个生灵自选修炼路径与节奏</td><td>选加速域还是求索域</td></tr><tr><td>种族层</td><td>每个种族自选文明发展方向</td><td>走科技路线还是法则路线</td></tr><tr><td>文明层</td><td>每个位面自选是否加入共生网络</td><td>自主决定，不强迫</td></tr></tbody></table><p>三层选择都受法律保护，任何强者、任何势力不得代为决定。</p><h2 id="二、选择不是任意-而是有边界的自由" tabindex="-1">二、选择不是任意，而是有边界的自由 <a class="header-anchor" href="#二、选择不是任意-而是有边界的自由" aria-label="Permalink to &quot;二、选择不是任意，而是有边界的自由&quot;">​</a></h2><p>自选命运不等于&quot;想干什么就干什么&quot;。边界是：<strong>你的自由止于他人的自由开始之处</strong>。具体而言：</p><ul><li>你可以选择不修炼、选择当凡人、选择过普通一生——被尊重；</li><li>你不能选择掠夺、奴役、伤害其他生灵——被禁止；</li><li>你不能选择把自己的命运强加给别人——被禁止。</li></ul><p>这与共生宪法（文档40）的基本精神完全一致：自由是有边界的自由，权利是与责任并行的权利。</p><h2 id="三、与唐罗-天选-叙事的对比" tabindex="-1">三、与唐罗&quot;天选&quot;叙事的对比 <a class="header-anchor" href="#三、与唐罗-天选-叙事的对比" aria-label="Permalink to &quot;三、与唐罗&quot;天选&quot;叙事的对比&quot;">​</a></h2><p>唐罗体系的核心叙事就是&quot;天选&quot;——只有主角一个人被命运选中，其他人的命运都是背景板。这种叙事在文学上好看，在政治上是灾难：它把&quot;被选中&quot;当作正当性的来源，把&quot;没被选中&quot;当作活该。衡元宙的自选命运机制反过来：<strong>没有谁被特别选中，每个生灵都被同样地尊重</strong>。</p><h2 id="三、选择权的代际传递" tabindex="-1">三、选择权的代际传递 <a class="header-anchor" href="#三、选择权的代际传递" aria-label="Permalink to &quot;三、选择权的代际传递&quot;">​</a></h2><p>万族自选命运机制还有一个时间维度：上一代为下一代选择的路，不能成为下一代的枷锁。每个生灵在成年（按其种族定义的成年节点）后，有权重新审视家族、种族、文明为他预设的路径，并作出自己的选择。系统会为这种&quot;重新选择&quot;提供完整的信息支持——把预设路径的利弊、其他路径的可能性都摆出来。代际选择不自由，自选命运就是空话；自选命运必须允许每一代人推翻上一代人的决定，哪怕那个决定曾经是对的。</p><h3 id="自选命运与文明多样性" tabindex="-1">自选命运与文明多样性 <a class="header-anchor" href="#自选命运与文明多样性" aria-label="Permalink to &quot;自选命运与文明多样性&quot;">​</a></h3><p>自选命运机制还带来一个意外的红利：文明多样性。当每个位面、每个种族都有权选择自己的节奏、技术方向、社会结构，整个共生网络就呈现出旧时代不可想象的多元形态——有的位面走科技路线，有的走法则路线，有的走两者融合。这种多样性不是混乱，而是万族共和公理的自然结果。它让共生网络在面对未来未知挑战时，有更多的&quot;备选文明&quot;可以借鉴。</p><h3 id="自选命运与文明契约" tabindex="-1">自选命运与文明契约 <a class="header-anchor" href="#自选命运与文明契约" aria-label="Permalink to &quot;自选命运与文明契约&quot;">​</a></h3><p>自选命运不是无政府。每个生灵在享受选择权的同时，也要签署一份文明契约：你的自由止于他人的自由开始。契约不是枷锁，而是让自选命运能持续运转的前提。没有契约，&quot;我选择掠夺&quot;也会被说成&quot;我的命运我做主&quot;。契约把选择权与责任绑在一起，让自选成为真正的权利，而不是放纵。</p><p>自选命运机制的最高理想，是让万族中的每一个生灵都能说出：&quot;我走的这条路，是我自己选的。&quot;这一句话，在旧体系里几乎没人有资格说。它不是修辞，它是文明的成就。</p><p>自选命运机制写进共生宪法第一条不是修辞，它意味着任何试图剥夺众生选择权的行为，都在违宪之列。这是衡元宙对万族最庄严的承诺。</p><h2 id="五大核心落点" tabindex="-1">五大核心落点 <a class="header-anchor" href="#五大核心落点" aria-label="Permalink to &quot;五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：让每个生灵走自己适合的路，避免被制度塞进不适合的轨道</li><li><strong>反掠夺</strong>：不替他人决定命运本身就是最大的反掠夺</li><li><strong>唐罗上限对比</strong>：唐罗是天选叙事，衡元宙是自选叙事</li><li><strong>万族全覆盖</strong>：五大谱系、男女老少、凡修圣修都有选择权</li><li><strong>超多元全开放</strong>：三层选择规则、边界条款、申诉渠道全部公开</li><li><strong>公理六·众生全员无限均等</strong>：所有生灵自带基础无限之力，佛系/懒狗保有保底基础无限不被时代淘汰，卷王与少年至尊可叠加更多更高层级的无限——无限本源人人自带，掠夺自然失去意义</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>把选择权交还给众生，不是文明的软弱，而是文明的成熟。衡元宙不试图替任何人安排命运，它只提供路、提供保护、提供资源——至于走哪条、走多快、走多远，由生灵自己决定。</p><p>说到底，本篇所述的万族自选命运总论并非孤例——其因果与能级留痕全程纳入阿赖耶网络备案、可溯可校。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./05-万族共进基本纲领">05-万族共进基本纲领</a> · <a href="./08-人人有路保障体系">08-人人有路保障体系</a> · <a href="./40-共生宪法总纲">40-共生宪法总纲</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',29)])])}const c=a(l,[["render",i]]);export{p as __pageData,c as default};
